import 'package:flutter/material.dart';
import '../services/api.dart';
import '../widgets/figma.dart';
import 'subject_detail_screen.dart';

class TeachersScreen extends StatefulWidget { const TeachersScreen({super.key}); @override State<TeachersScreen> createState()=>_TeachersScreenState(); }
class _TeachersScreenState extends State<TeachersScreen>{ final api=const LarniaApi(); List<dynamic> teachers=[]; @override void initState(){super.initState(); load();} Future<void> load() async{teachers=await api.list('/api/teachers'); if(mounted)setState((){});} Future<void> createTeacher() async{final name=TextEditingController(); final subject=TextEditingController(); final ok=await showDialog<bool>(context: context, builder:(_)=>AlertDialog(title: const Text('Vytvoriť učiteľa', style: TextStyle(color: blue)), content: Column(mainAxisSize: MainAxisSize.min, children:[TextField(controller:name, decoration: const InputDecoration(labelText:'Názov učiteľa')), TextField(controller:subject, decoration: const InputDecoration(labelText:'Predmet'))]), actions:[FigmaButton(text:'Zrušiť', color:blue2, width:120, onPressed:()=>Navigator.pop(context,false)), FigmaButton(text:'+ Vytvoriť', width:160, onPressed:()=>Navigator.pop(context,true))])); if(ok==true && name.text.trim().isNotEmpty){await api.post('/api/teachers', {'name':name.text.trim(),'subject':subject.text.trim()}); await load();}}
@override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.white, body:Padding(padding: const EdgeInsets.fromLTRB(45,80,45,80), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children:[const LarniaHeader(title:'Môj smart učiteľ', subtitle:'Váš prístup k interaktívnemu vzdelávaniu začína tu.'), const SizedBox(height:17), Row(children:[FigmaButton(text:'Odstrániť', color:blue2, width:162), const SizedBox(width:17), FigmaButton(text:'+ Vytvoriť učiteľa', width:222, onPressed:createTeacher)]), const Spacer(), SizedBox(height:280, child: teachers.isEmpty ? Center(child: TextButton(onPressed:createTeacher, child: const Text('+ Vytvoriť učiteľa', style:TextStyle(color:blue, fontSize:24)))) : ListView.separated(scrollDirection: Axis.horizontal, itemCount:teachers.length, separatorBuilder:(_,__)=>const SizedBox(width:34), itemBuilder:(_,i)=>FigmaCard(width:280,height:280,onTap:()=>Navigator.push(context, MaterialPageRoute(builder:(_)=>SubjectDetailScreen(teacher:teachers[i]))), child:Column(mainAxisAlignment: MainAxisAlignment.center, children:[const LarniaMark(size:118), const SizedBox(height:20), Text(teachers[i]['name'], style: const TextStyle(color:blue, fontSize:24,fontWeight:FontWeight.w600))])))]))));}
